    max_partition = []
    min_partition = []
    max_score = float('-inf')
    min_score = float('inf')

    def backtrack(current_partition, current_factors, current_score):
        nonlocal max_partition, min_partition, max_score, min_score
        if current_score > max_score:
            max_partition = current_partition[:]
            max_score = current_score
        if current_score < min_score:
            min_partition = current_partition[:]
            min_score = current_score

        for factor, freq in current_factors.items():
            if freq > 1:
                current_partition.append(factor)
                backtrack(current_partition, {f: freq - 1 for f in current_factors if f != factor}, current_score + factor)
                current_partition.pop()

    backtrack([], factors, 0)

    if com == 'max':
        return [max_partition, max_score]
    else:
        return [min_partition, min_score]
