def find_spec_prod_part(n, com):
    if n <= 1 or n == 2:
        return "It is a prime number"

    def is_prime(num):
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True

    if is_prime(n):
        return "It is a prime number"

    def prime_factors(n):
        i = 2
        factors = []
        while i * i <= n:
            if n % i:
                i += 1
            else:
                n //= i
                factors.append(i)
        if n > 1:
            factors.append(n)
        return factors

    factors = prime_factors(n)
    factor_counts = {}
    for factor in factors:
        if factor in factor_counts:
            factor_counts[factor] += 1
        else:
            factor_counts[factor] = 1

    from itertools import combinations_with_replacement
    from operator import mul
    from functools import reduce

    def calculate_score(factors):
        return reduce(mul, (factor ** count for factor, count in factor_counts.items()), 1) * len(factors)

    max_partition = []
    max_score = float('-inf')
    min_partition = []
    min_score = float('inf')

    for r in range(1, len(factors) + 1):
        for combo in combinations_with_replacement(factors, r):
            if len(combo) == r:
                score = calculate_score(combo)
                if score > max_score:
                    max_score = score
                    max_partition = sorted(combo, reverse=True)
                if score < min_score:
                    min_score = score
                    min_partition = sorted(combo, reverse=True)

    if com == 'max':
        return [max_partition, max_score]
    elif com == 'min':
        return [min_partition, min_score]
    else:
        raise ValueError("Invalid command. Use 'max' or 'min'.")
