def word_to_num(word):
    # Define mappings for words to numbers
    units = {
        "zero": 0, "one": 1, "two": 2, "three": 3, "four": 4,
        "five": 5, "six": 6, "seven": 7, "eight": 8, "nine": 9,
        "ten": 10, "eleven": 11, "twelve": 12, "thirteen": 13,
        "fourteen": 14, "fifteen": 15, "sixteen": 16, "seventeen": 17,
        "eighteen": 18, "nineteen": 19
    }
    tens = {
        "twenty": 20, "thirty": 30, "forty": 40, "fifty": 50,
        "sixty": 60, "seventy": 70, "eighty": 80, "ninety": 90
    }
    scales = {
        "hundred": 100, "thousand": 1000, "million": 1000000
    }

    # Helper function to parse a chunk of words
    def parse_chunk(chunk):
        total = 0
        current = 0
        scale = 1
        for word in chunk.split():
            if word in units:
                current += units[word]
            elif word in tens:
                current += tens[word]
            elif word in scales:
                scale = scales[word]
                if scale > 1:
                    total += current * scale
                    current = 0
        total += current * scale
        return total

    # Split the word by 'and' and parse each chunk
    chunks = word.replace(" and ", " ").split()
    result = 0
    for chunk in chunks:
        result += parse_chunk(chunk)

    return result
