        return int(n**0.5)**2

    def is_valid_solution(solution: list) -> bool:
        return sum(x**2 for x in solution) == n**2 and all(solution[i] < solution[i + 1] for i in range(len(solution) - 1))

    def decompose_recursive(n: int, current_solution: list) -> list:
        if n == 0:
            return current_solution
        largest_square = find_largest_square(n)
        if largest_square == 0:
            return None
        for i in range(largest_square, 0, -1):
            if is_valid_solution(current_solution + [i]):
                result = decompose_recursive(n - i, current_solution + [i])
                if result is not None:
                    return result
        return None

    result = decompose_recursive(n, [])
    if result is None:
        return None
    return result
