def to_chinese_numeral(n):
    def construct_number(number, is_decimal=False):
        if number == 0:
            return "零" if is_decimal else "零"
        chinese_numerals = {
            0: "零", 1: "一", 2: "二", 3: "三", 4: "四", 5: "五",
            6: "六", 7: "七", 8: "八", 9: "九"
        }
        place_multipliers = {
            1: "", 10: "十", 100: "百", 1000: "千", 10000: "万"
        }
        result = []
        place = 1
        while number > 0:
            digit = number % 10
            if digit == 0:
                if result and result[-1] != "零":
                    result.append("零")
            else:
                if result and result[-1] == "零":
                    result.pop()
                result.append(chinese_numerals[digit] + place_multipliers[place])
            number //= 10
            place *= 10
        return ''.join(reversed(result))

    if n == 0:
        return "零"
    if n < 0:
        return "负" + to_chinese_numeral(-n)
    whole_number = int(n)
    decimal_part = int((n - whole_number) * 100000000)
    whole_result = construct_number(whole_number)
    decimal_result = construct_number(decimal_part, is_decimal=True)
    if decimal_result == "零":
        return whole_result
    return whole_result + "点" + decimal_result
